class HelloViewIT extends SpringBrowserlessTest {

    @Test
    void greetingIsShown() {
        MainView view = navigate(MainView.class);

        TextField nameField = $(TextField.class).withLabel("Your name").single();
        test(nameField).setValue("Alice");

        Button greetButton = $(Button.class).withCaption("Say hello").single();
        test(greetButton).click();

        Span greeting = $(Span.class).single();
        assertEquals("Hello, Alice!", test(greeting).getText());
    }
}
```

